test('tc-12: Reset link at exact moment of expiration boundary', async ({ page }) => {
  await page.goto('https://example-app-placeholder.com/password-reset');

  const requestResetButton = page.locator('[data-testid="request-reset-button"]');
  const emailInput = page.locator('[data-testid="email-input"]');

  await emailInput.fill('test@example.com');
  const requestTimestamp = Date.now();
  await requestResetButton.click();

  // Retrieve reset link from email or test helper
  const resetLink = 'https://example-app-placeholder.com/reset-password?token=placeholder-token';

  // Wait until exactly 3600 seconds (1 hour) from request timestamp
  const targetTime = requestTimestamp + (3600 * 1000);
  const waitDuration = targetTime - Date.now();
  if (waitDuration > 0) {
    await page.waitForTimeout(waitDuration);
  }

  await page.goto(resetLink);

  const newPasswordInput = page.locator('[data-testid="new-password-input"]');
  const confirmPasswordInput = page.locator('[data-testid="confirm-password-input"]');
  const submitButton = page.locator('[data-testid="submit-new-password-button"]');

  await newPasswordInput.fill('NewSecurePassword123!');
  await confirmPasswordInput.fill('NewSecurePassword123!');
  await submitButton.click();

  // Assert consistent expiration logic: either success message or expiration error
  const successMessage = page.locator('[data-testid="password-reset-success-message"]');
  const expirationError = page.locator('[data-testid="reset-link-expired-error"]');

  // Check that exactly one of these conditions is true consistently
  const isSuccess = await successMessage.isVisible().catch(() => false);
  const isExpired = await expirationError.isVisible().catch(() => false);

  expect(isSuccess || isExpired).toBeTruthy(); // One outcome must occur
  expect(isSuccess && isExpired).toBeFalsy(); // But not both simultaneously
});
